import sys
sys.setrecursionlimit(10000)
d = sys.stdin.read().split()
n, m, S = int(d[0]), int(d[1]), int(d[2])
k = 3
g = []
for _ in range(2):
    rows = []
    for i in range(n):
        rows.append([int(x) for x in d[k:k + m]])
        k += m
    g.append(rows)

def f(i, j, cur):
    cost = g[cur][i][j]
    if i == n - 1 and j == m - 1:
        return cost
    best = None
    for ni, nj in ((i + 1, j), (i, j + 1)):
        if ni < n and nj < m:
            for ng in (0, 1):
                v = f(ni, nj, ng) + (S if ng != cur else 0)
                if best is None or v < best:
                    best = v
    return cost + best

print(f(0, 0, 0))

